//! The Helix configuration (`KLF-EDITOR.md` section 19.8 item 2).

use crate::treesitter::{Dialect, queries_for};
use crate::{File, Language};
use std::fmt::Write;

fn toml_string(text: &str) -> String {
    format!("{text:?}")
}

fn toml_list(items: &[String]) -> String {
    let quoted: Vec<String> = items.iter().map(|item| toml_string(item)).collect();
    format!("[{}]", quoted.join(", "))
}

pub(crate) fn package(language: &Language) -> Vec<File> {
    let spec = &language.spec;
    let id = language.identifier();
    let mut text = format!(
        "# Generated by klf editor gen. Merge into ~/.config/helix/languages.toml and\n\
         # copy queries/ into ~/.config/helix/runtime/queries/.\n\n\
         [[language]]\nname = {}\nscope = {}\nfile-types = {}\nroots = {}\nlanguage-servers = [{}]\ngrammar = {}\n",
        toml_string(&id),
        toml_string(&spec.scope),
        toml_list(&language.extensions),
        toml_list(&spec.root_markers),
        toml_string(&format!("{id}-lsp")),
        toml_string(&id),
    );
    if !spec.line_comments.is_empty() {
        let _ = writeln!(text, "comment-tokens = {}", toml_list(&spec.line_comments));
    }
    if let Some(block) = spec.block_comments.first() {
        let _ = writeln!(
            text,
            "block-comment-tokens = {{ start = {}, end = {} }}",
            toml_string(&block.open),
            toml_string(&block.close)
        );
    }
    let _ = writeln!(
        text,
        "indent = {{ tab-width = {}, unit = {} }}",
        spec.indent.unit.chars().count().max(1),
        toml_string(&spec.indent.unit)
    );
    let _ = write!(
        text,
        "\n# Helix runs the server from PATH; to use a sysroot, set `command` to\n\
         # the value of {sysroot} followed by /bin/{driver}.\n\
         [language-server.{id}-lsp]\ncommand = {}\nargs = [\"lsp\"]\n\n[[grammar]]\nname = {}\n",
        toml_string(&language.driver),
        toml_string(&id),
        sysroot = language.sysroot_variable(),
        driver = language.driver,
    );
    if let Some(grammar) = &spec.grammar {
        let _ = writeln!(
            text,
            "source = {{ git = {}, rev = {}, subpath = {} }}",
            toml_string(&grammar.repository),
            toml_string(&grammar.revision),
            toml_string(&grammar.path)
        );
    } else {
        text.push_str("# The lexical grammar of this tree; replace with its absolute path.\n");
        text.push_str("source = { path = \"../tree-sitter\" }\n");
    }
    let mut files = vec![File::text("helix/languages.toml", text)];
    if let Ok(queries) = queries_for(language, Dialect::Helix) {
        for (name, query) in queries {
            if matches!(
                name,
                "highlights.scm" | "indents.scm" | "textobjects.scm" | "injections.scm"
            ) {
                files.push(File::text(format!("helix/queries/{id}/{name}"), query));
            }
        }
    }
    files
}
